// Sample ink from name region: darkest pixels that are not pure stamp-red
func sampleInk(_ image: CGImage, rect: CGRect) -> (r:Int,g:Int,b:Int) {
    let c = cropTL(image, rect: rect)
    let w = c.width, h = c.height
    var data = [UInt8](repeating: 0, count: w*h*4)
    let ctx = CGContext(data: &data, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w*4, space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    ctx.draw(c, in: CGRect(x:0,y:0,width:w,height:h))
    var sumR=0,sumG=0,sumB=0,cnt=0
    // collect pixels with low luminance but not strongly red-dominant (stamp)
    var pixels: [(Int,Int,Int,Int)] = [] // r,g,b,lum
    for y in 0..<h {
        for x in 0..<w {
            let i = (y*w+x)*4
            let r=Int(data[i]), g=Int(data[i+1]), b=Int(data[i+2])
            let lum = (r+g+b)/3
            // skip bright paper and strong red stamp
            if lum > 140 { continue }
            if r > g + 40 && r > b + 40 { continue }
            pixels.append((r,g,b,lum))
        }
    }
    pixels.sort { $0.3 < $1.3 }
    let take = max(1, pixels.count / 3) // darkest third
    for i in 0..<take {
        sumR += pixels[i].0; sumG += pixels[i].1; sumB += pixels[i].2; cnt += 1
    }
    return (sumR/max(cnt,1), sumG/max(cnt,1), sumB/max(cnt,1))
}
